      "name": {
        "type": "string",
        "description": "常去咖啡馆名称的脱敏样例展示文本。",
        "sampleValue": "常去咖啡馆"
      },
      "addressLine": {
        "type": "string",
        "description": "常去咖啡馆地址的脱敏样例展示文本。",
        "sampleValue": "中山路88号"
      }
    },
    "action": {
      "navigateLabel": {
        "type": "string",
        "description": "地图导航入口的短标签。",
        "sampleValue": "导航"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bell_slash_fill.svg",
      "description": "铃铛加斜杠的静音图标，适合表达冥想、勿扰或关闭通知状态；黑白双色 SVG，深色背景上应放在浅色图标底板内使用。"
    }
  ]
}

